head.script:
scwin.hasClass = function() {
    var el = WebSquare.wUnit.getDomById($p.id + "gv3_column1_filter");
    return el.classList.contains("w2grid_customFilter_open");
}
scwin.checktype = function() {
    return typeof gv3_column1_filter;
}
scwin.checkVal = function() {
    return WebSquare.wUnit.getDomById('gv3_cell_0_3').innerText == 5;
}
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");

    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv3').getAttribute('useFilterList')", "true");
    //WebSquare.wUnit.addCommand("pause", "500");

    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv3').getAttribute('showSortableImage')", "true");
    WebSquare.wUnit.addCommand("pause", "1000");

    //WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById('gv3').getAttribute('showSortableUseFilter')", "true");
    //WebSquare.wUnit.addCommand("pause", "500");

    //WebSquare.wUnit.addCommand("assert", "scwin.checktype()", "object");
    //WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gv3_column1_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById($p.id+'gv3_customFilter_list').childNodes[0].click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gv3_item_0_selectbox_column1').setText('=')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gv3_item_0_autocomplete_column1').setText('5')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('gv3_btnConform_column1').click()");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();

